function previewFile(e,n){const t=document.getElementById(n),i=e.files[0];if(i){const e=new FileReader;e.onload=function(e){t.innerHTML=`<img src="${e.target.result}" alt="Uploaded Image" />`,t.style.display="block"},e.readAsDataURL(i)}else t.innerHTML="",t.style.display="none"}function goBack(){history.back()}